#!/usr/bin/env node
/**
 * Generates lib/generated/themes-bundle.js — the include-chain-flattened
 * `colors` + `tokenColors` + `type` for every contributed variant, keyed by
 * name/label/path/uiTheme.
 *
 * The runtime (Theme Gallery, terminal & editor/UI contrast verification) reads
 * this embedded data instead of touching the filesystem, so those features work
 * in the **web** extension host (vscode.dev / github.dev) where Node's `fs` is
 * unavailable. Also writes `docs/landing-themes.js` so the GitHub Pages gallery
 * uses the same editor.background / foreground / accent as the extension.
 * Wired into `make:full` after `fix:ui-contrast` so both outputs reflect the
 * final, contrast-fixed themes.
 *
 * Run: node scripts/build-themes-bundle.mjs
 */
import fs from "fs";
import path from "path";
import { fileURLToPath } from "url";
import { createRequire } from "module";

const require = createRequire(import.meta.url);
const { mergeThemeData } = require("../lib/themes/theme-merge-data.js");
const { stripThemeDisplayLabel } = require("../lib/themes/theme-common.js");
const { buildLandingThemeEntry } = require("../lib/themes/landing-preview.js");

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.join(__dirname, "..");
const outDir = path.join(root, "lib", "generated");
const outFile = path.join(outDir, "themes-bundle.js");

const pkg = JSON.parse(fs.readFileSync(path.join(root, "package.json"), "utf8"));
const themes = pkg?.contributes?.themes;
if (!Array.isArray(themes)) {
  console.error("package.json: contributes.themes missing");
  process.exit(1);
}

const entries = [];
for (const theme of themes) {
  if (typeof theme?.path !== "string" || !theme.path.endsWith(".json")) continue;
  const full = path.resolve(root, theme.path);
  if (!fs.existsSync(full)) continue;
  const label = typeof theme.label === "string" ? theme.label : "";
  const data = mergeThemeData(full);
  entries.push({
    name: stripThemeDisplayLabel(label) || label,
    label,
    path: theme.path,
    uiTheme: typeof theme.uiTheme === "string" ? theme.uiTheme : "vs-dark",
    type: data.type || (theme.uiTheme === "vs" ? "light" : "dark"),
    colors: data.colors,
    tokenColors: data.tokenColors,
  });
}

const header =
  "// AUTO-GENERATED by scripts/build-themes-bundle.mjs — do not edit by hand.\n" +
  "// Pre-merged theme data (include chain flattened) embedded for the web host.\n" +
  "// Regenerate with `npm run build:bundle` (runs inside `make:full`).\n";

fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(outFile, `${header}module.exports = ${JSON.stringify(entries)};\n`);

const landingFile = path.join(root, "docs", "landing-themes.js");
const landingHeader =
  "// AUTO-GENERATED by scripts/build-themes-bundle.mjs — do not edit by hand.\n" +
  "// Compact editor swatches for the GitHub Pages landing gallery.\n" +
  "// Regenerate with `npm run build:bundle` (runs inside `make:full`).\n";
const landing = entries.map((entry) => buildLandingThemeEntry(entry));
fs.writeFileSync(
  landingFile,
  `${landingHeader}globalThis.DUSK_OFFICE_LANDING_THEMES = ${JSON.stringify(landing)};\n`,
);

console.log(
  `OK themes-bundle: ${entries.length} variants → ${path.relative(root, outFile)}` +
    ` · landing → ${path.relative(root, landingFile)}`,
);
